PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?totalCashFlow ?avgGoalProgress ?avgHoldingReturn ?riskScore ?totalAllocationPct
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId ?riskScore
    WHERE {
      ?phl a wm:PortfolioHealth ;
            wm:investorId ?investorId ;
            wm:riskScore ?riskScore .
