PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?timeHorizon ?totalCashFlow ?avgGoalProgress ?avgHoldingReturn ?riskScore ?totalAllocationPct
WHERE {
  {
    SELECT DISTINCT ?investorId ?timeHorizon
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:timeToGoalMonths ?timeHorizon .
    }
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore)
    WHERE {
      ?phl a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?allocationPct)) AS ?totalAllocationPct)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
}
ORDER BY ?investorId ?timeHorizon
